select t0.docdate ,t3.DistNumber, t0.Quantity, t0.docentry, t0.itemcode, 'Nhap'as Loai from IGN1 t0inner join OITL t1 on t0.DocEntry = t1.DocEntry and t1.DocType = 59inner join ITL1 t2 on t1.LogEntry = t2.LogEntryinner join OBTN t3 on t2.ItemCode = t3.ItemCode and t2.SysNumber = t3.SysNumberwhere t0.U_belnrid =[%0] and t0.U_belposid = [%1] and t0.itemcode = '[%2]'union allselect t0.docdate, t3.DistNumber, - t0.Quantity, t0.docentry, t0.itemcode, 'Xuat'as Loai from IGE1 t0inner join OITL t1 on t0.DocEntry = t1.DocEntry and t1.DocType = 60inner join ITL1 t2 on t1.LogEntry = t2.LogEntryinner join OBTN t3 on t2.ItemCode = t3.ItemCode and t2.SysNumber = t3.SysNumberwhere t0.U_belnrid =[%0] and t0.U_belposid = [%1] and t0.itemcode = '[%2]'order by t3.DistNumber